use crate::{ivp_managed_response::{ResponseWorld,Body,Object,Feature,Settings},ivp_contact_pipeline::CoreFrame,ivp_contact::Core,ivp_create::{Endpoint,Feature as CompactFeature},ivp_managed_contacts::Settings as AdmissionSettings,ivp_refresh,ivp_unit_registry::Registry};
use bevy::prelude::*;
use serde_json::Value;
fn f(v:&Value)->f32{v.as_f64().unwrap() as f32}
fn vec(v:&Value)->Vec3{Vec3::from_array(std::array::from_fn(|i|f(&v[i])))}
fn rows(v:&Value)->[Vec3;3]{std::array::from_fn(|i|vec(&v[i]))}
fn endpoint(e:&Value)->Endpoint{let v=&e["feature"];Endpoint{object:e["object"].as_u64().unwrap(),feature:CompactFeature{kind:v["kind"].as_i64().unwrap() as i16,edge:v["edge"].as_u64().unwrap(),opposite:v["opposite"].as_u64().unwrap(),triangle:v["triangle"].as_u64().unwrap(),ledge:v["ledge"].as_u64().unwrap(),vertex:v["vertex"].as_u64().unwrap() as u16,vertices:rows(&v["vertices"])}}}
fn physical_bank(bodies:Vec<Body>,c:&Value)->Vec<crate::ivp_joint_apply::Body>{bodies.into_iter().enumerate().map(|(i,b)|{let pad=f32::from_bits(0x7fc01200+i as u32);let lanes=|v:Vec3|[v.x,v.y,v.z,pad];let q=Quat::from_mat3(&b.frame.rotation).to_array();crate::ivp_joint_apply::Body{id:i,flags:b.flags,object_flags:0x1001,mass:f(&c["bodies"][i]["mass"]),inverse:[b.core.inverse_inertia.x,b.core.inverse_inertia.y,b.core.inverse_inertia.z,b.core.inverse_mass],current:crate::ivp_motion::Pose{position:b.frame.position,rotation:b.frame.rotation},prediction:crate::ivp_motion::Prediction{start:b.frame.position,velocity:b.core.linear,rotation_start:q,rotation_end:q,time:c["time"].as_f64().unwrap(),inverse_dt:f(&c["dt"]).recip()},clock:c["time"].as_f64().unwrap(),stamps:b.stamps,pending_angular:lanes(b.core.pending_angular),pending_linear:lanes(b.core.pending_linear),angular:lanes(b.core.angular),linear:lanes(b.core.linear)}}).collect()}
fn opaque(w:&ResponseWorld)->Value{serde_json::json!(w.physical_bodies().unwrap().iter().map(|b|serde_json::json!({"id":b.id,"flags":b.flags,"object_flags":b.object_flags,"mass":b.mass.to_bits(),"inverse":b.inverse.map(f32::to_bits),"position":b.current.position.to_array().map(f32::to_bits),"rotation":b.current.rotation.to_cols_array().map(f32::to_bits),"clock":b.clock.to_bits(),"predictor":[b.prediction.time.to_bits(),b.prediction.inverse_dt.to_bits() as u64],"prediction_start":b.prediction.start.to_array().map(f32::to_bits),"prediction_velocity":b.prediction.velocity.to_array().map(f32::to_bits),"prediction_q0":b.prediction.rotation_start.map(f32::to_bits),"prediction_q1":b.prediction.rotation_end.map(f32::to_bits),"padding":([b.linear[3],b.angular[3],b.pending_linear[3],b.pending_angular[3]].map(f32::to_bits))})).collect::<Vec<_>>())}
fn frames(c:&Value)->Vec<(u64,[Vec3;3],Vec3)>{let mut all=std::collections::BTreeMap::new();for b in c["births"].as_array().unwrap(){for i in 0..2{let id=b["endpoints"][i]["object"].as_u64().unwrap();all.insert(id,(id,rows(&b["shapes"][i]["rotation"]),vec(&b["shapes"][i]["translation"])));}}all.into_values().collect()}
fn world(c:&Value)->ResponseWorld{
    let mut registry=Registry::new(4);let bodies=c["bodies"].as_array().unwrap().iter().enumerate().map(|(i,v)|{let flags=v["flags"].as_u64().unwrap() as u16;registry.register_core(i,flags&2!=0).unwrap();Body{flags,core:Core{inverse_mass:f(&v["inverse_mass"]),inverse_inertia:vec(&v["inverse_inertia"]),linear:vec(&v["linear"]),angular:vec(&v["angular"]),pending_linear:vec(&v["pending_linear"]),pending_angular:vec(&v["pending_angular"])},frame:CoreFrame{rotation:Mat3::from_cols_array_2d(&rows(&v["rotation"]).map(|v|v.to_array())).transpose(),position:vec(&v["position"])},stamps:std::array::from_fn(|i|v["stamps"][i].as_f64().unwrap())}}).collect();
    let mut objects=std::collections::BTreeMap::new();for birth in c["births"].as_array().unwrap(){for side in 0..2{let e=&birth["endpoints"][side];let core=e["object"].as_u64().unwrap() as usize-1;let shape=&birth["shapes"][side];let m=&c["bodies"][core]["material"];let o=Object{core,rotation:rows(&shape["rotation"]),translation:vec(&shape["translation"]),radius:f(&shape["radius"]),material_flags:m["flags"].as_u64().unwrap() as u32,friction:f(&m["friction"])};if let Some(old)=objects.insert(core as u64+1,o){assert_eq!(old.rotation,o.rotation);assert_eq!(old.translation,o.translation);assert_eq!(old.radius,o.radius);}}}
    let k=&c["settings"];ResponseWorld::new_physical(registry,physical_bank(bodies,c),objects,Settings{dt:f(&c["dt"]),admission:AdmissionSettings{distance:f(&k["distance"]),area_epsilon:k["area_epsilon"].as_f64().unwrap()},refresh:ivp_refresh::Settings{epsilon:f(&k["epsilon"]),bary_bias:f(&k["bary_bias"]),area_epsilon:k["area_epsilon"].as_f64().unwrap(),one:f(&k["one"]),opposite:f(&k["opposite"])},threshold_extra:f(&k["threshold_extra"]),minimum_impulse:f(&k["minimum_impulse"]),minimum_determinant_squared:f(&k["minimum_determinant_squared"])},c["time"].as_f64().unwrap()).unwrap()
}
fn features(c:&Value)->[Feature;2]{std::array::from_fn(|i|Feature{endpoint:endpoint(&c["endpoints"][i]),vertices:rows(&c["shapes"][i]["vertices"]),canonical:rows(&c["shapes"][i]["canonical"])})}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){
    (Value::Object(a),Value::Object(b))=>for(k,v)in a{compare(v,&b[k],&format!("{path}.{k}"));},
    (Value::Array(a),Value::Array(b))=>{assert_eq!(a.len(),b.len(),"{path}");for(i,(a,b))in a.iter().zip(b).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},
    (Value::Number(a),Value::Number(b))=>{if path.ends_with(".time")||path.contains(".stamps["){assert_eq!(a.as_f64().unwrap().to_bits(),b.as_f64().unwrap().to_bits(),"{path}");}else if a.is_f64()||b.is_f64(){assert_eq!((a.as_f64().unwrap() as f32).to_bits(),(b.as_f64().unwrap() as f32).to_bits(),"{path}: {a} vs {b}");}else{assert_eq!(a,b,"{path}");}},
    _=>assert_eq!(a,b,"{path}"),
}}

fn configured(c:&Value)->ResponseWorld{let mut b=c.clone();b["endpoints"]=c["births"][0]["endpoints"].clone();b["shapes"]=c["births"][0]["shapes"].clone();world(&b).with_energy(c["bodies"].as_array().unwrap().iter().map(|v|crate::ivp_batch_normal::Physical{flags:v["flags"].as_u64().unwrap() as u16,mass:f(&v["mass"]),inertia:vec(&v["inertia"])}).collect(),f(&c["allowance_factor"]),f(&c["energy_bound"])).unwrap()}

pub(crate) fn configured_pipeline(c:&Value)->ResponseWorld{let w=&c["work"];let k=&w["settings"];configured(c).with_pair_work(f(&w["coefficient"]),f(&w["initial"]),w["blocked"].as_array().unwrap().iter().map(|b|b.as_bool().unwrap()).collect(),crate::ivp_dissipation::Settings{epsilon:f(&k["epsilon"]),one:f(&k["one"]),opposite:f(&k["opposite"]),two:f(&k["two"]),half:f(&k["half"]),huge:f(&k["huge"]),small:f(&k["small"]),fraction:f(&k["fraction"])}).unwrap()}

fn snapshot(w:&ResponseWorld)->Value{let mut v=w.world_snapshot();let graph=w.registry().controller_snapshot();let mut units=graph["units"].as_array().unwrap().iter().filter(|u|u["cores"].as_array().unwrap().iter().any(|c|c.as_u64().unwrap()<4)).map(|u|serde_json::json!({"cores":u["cores"],"controllers":u["controllers"].as_array().unwrap().iter().map(|r|serde_json::json!({"kind":r["controller"]["kind"],"cores":r["cores"]})).collect::<Vec<_>>()})).collect::<Vec<_>>();units.sort_by_key(|u|u["cores"].as_array().unwrap().iter().map(|c|c.as_u64().unwrap()).min().unwrap());v["unit_graph"]=serde_json::json!(units);v}
fn replay_split(c:&Value,check:bool)->Vec<Value>{let mut w=configured_pipeline(c);let mut context=frames(c);let mut now=c["time"].as_f64().unwrap();let before=format!("{:?}",w.registry());assert!(w.finish_unit_graph(99).is_err());assert_eq!(format!("{:?}",w.registry()),before);let mut all=vec![];for b in c["births"].as_array().unwrap(){let mut input=c.clone();input["endpoints"]=b["endpoints"].clone();input["shapes"]=b["shapes"].clone();let id=w.resolve(0xc0000,features(&input),Some(1)).unwrap().unwrap();let actual=w.snapshot(id);if check{compare(&actual,&b["numeric"],"split admission");}all.push(actual);}let initial=snapshot(&w);if check{compare(&initial,&c["states"][0]["output"],"split initial");}all.push(initial);w.take_effects();
for(i,row)in c["states"].as_array().unwrap().iter().enumerate().skip(1){let mut changes=vec![crate::ivp_managed_response::StepChange{core:1,linear:vec(&row["kick"]),angular:vec(&row["angular"]),translation:vec(&row["shift"])}];for (id,key) in [(2,"second_shift"),(3,"third_shift")]{let delta=vec(&row[key]);if delta!=Vec3::ZERO{changes.push(crate::ivp_managed_response::StepChange{core:id,linear:Vec3::ZERO,angular:Vec3::ZERO,translation:delta});}}for change in &changes{let body=&mut w.physical_bodies_mut().unwrap()[change.core];for i in 0..3{body.linear[i]+=change.linear[i];body.angular[i]+=change.angular[i];}body.current.position+=change.translation;for (id,_,p) in &mut context{if *id==change.core as u64+1{*p+=change.translation;}}}now+=f(&c["dt"]) as f64;w.set_physical_context(now,&context).unwrap();let order=w.system_ids();for phase in 0..3{let preserved=opaque(&w);for &system in &order{match phase{0=>w.refresh(system).unwrap(),1=>w.tangent(system).unwrap(),_=>{w.normal(system).unwrap();}}}if phase==2{for core in 1..4{w.finish_unit_graph(core).unwrap();}}assert_eq!(opaque(&w),preserved,"contact callback changed physical predictor/padding");let actual=snapshot(&w);if check{compare(&actual,&row["phases"][phase],&format!("world{} split step{i} phase{phase}",c["scenario"]));}all.push(actual);}}
let(effects,ids,features)=w.take_effects();assert_eq!(ids.len(),c["births"].as_array().unwrap().len());assert_eq!(features.len(),ids.len());assert_eq!(effects.iter().filter(|e|matches!(e,crate::ivp_unit_registry::Effect::ResetClock(_))).count(),2*ids.len());assert!(w.system_ids().is_empty());all}
pub(crate) fn verify(){let data:Value=serde_json::from_str(include_str!("../tools/fixtures/native-ivp-contact-graph-pipeline.json")).unwrap();let mut count=0;for c in data["cases"].as_array().unwrap(){let actual=replay_split(c,true);count+=actual.len();let mut bad=c.clone();for b in bad["births"].as_array_mut().unwrap(){b["numeric"]=Value::Null;}bad["states"][0]["output"]=Value::Null;for row in bad["states"].as_array_mut().unwrap().iter_mut().skip(1){row["phases"]=Value::Null;}assert_eq!(actual,replay_split(&bad,false));}assert_eq!(count,415);invalid(&data["cases"][0]);println!("physical-bank native contact continuation:8 worlds /95 births /415 checkpoints; full body bank owns velocities and preserves predictors, properties and opaque fourth lanes");}
fn invalid(c:&Value){
 let mut authored=crate::ivp_contact_graph_pipeline_tests::configured_pipeline(c);assert!(authored.physical_bodies().is_err());assert!(authored.physical_bodies_mut().is_err());
 let bank=physical_bank(authored.body_views().collect(),c);let initial=(authored.world_snapshot(),authored.diagnostics());
 let mut bad=bank.clone();bad.last_mut().unwrap().prediction.time=f64::NAN;assert!(authored.adopt_physical_bodies(bad).is_err());assert_eq!((authored.world_snapshot(),authored.diagnostics()),initial);
 let mut bad=bank.clone();bad.last_mut().unwrap().linear[0]+=0.125;assert!(authored.adopt_physical_bodies(bad).is_err());assert_eq!((authored.world_snapshot(),authored.diagnostics()),initial);
 let mut bad=bank.clone();bad.last_mut().unwrap().mass+=1.;assert!(authored.adopt_physical_bodies(bad).is_err());assert_eq!((authored.world_snapshot(),authored.diagnostics()),initial);
 authored.adopt_physical_bodies(bank).unwrap();let before=(authored.world_snapshot(),authored.diagnostics(),opaque(&authored));assert!(authored.advance_many(&[]).is_err());assert!(authored.adopt_physical_bodies(authored.physical_bodies().unwrap().to_vec()).is_err());
 let good=frames(c);let mut bad=good.clone();bad.last_mut().unwrap().2.x=f32::NAN;assert!(authored.set_physical_context(99.,&bad).is_err());let mut bad=good.clone();bad.last_mut().unwrap().0=good[0].0;assert!(authored.set_physical_context(99.,&bad).is_err());assert!(authored.set_physical_context(f64::NAN,&good).is_err());assert_eq!((authored.world_snapshot(),authored.diagnostics(),opaque(&authored)),before);
}
#[test]fn native_physical_bank_contact_numerics_and_opaque_fields_match(){verify();}
